"""Verdict process: compare every assertion with GOA (graph urn:locx:graph:verdicts), generated by its own
activity (a locx:VerdictComputation, locx:verdictRun/<time>) that records what it used: the GO, ECO and locx ontology releases, the GOA
file, the assertions, and the rule files. Runs after the support process (locx/analysis/support.py).

  python -m locx.analysis.verdicts [--run-id ID] [--replace]
  python -m locx.analysis.verdicts --support-only   # only refresh "support_by_verdict" in verdicts.json

1. queries/verdicts_01_goa_links.ru, verdicts_02_rules.ru: one locx:Verdict per assertion with its outcome, the GOA
   rows behind it, the strongest GO evidence category (ECO hierarchy + locx ontology) and same-paper curation.
2. Reports: verdicts.json, assertion_stats.tsv, top_novel.tsv, top_conflicting.tsv (outcomes joined with the support
   counts in data/interim/support_stats.jsonl).
The verdicts graph is rebuilt from scratch; a non-empty graph is only dropped with --replace.
"""
import argparse
import csv
import hashlib
import json
import sys
import time
from collections import Counter, defaultdict
from datetime import datetime, timezone

from locx import evidence
from locx import ontology as O
from locx.config import CFG, INTERIM, QUERIES, RDF, REPORTS
from locx.io import read_jsonl
from locx.kg import fuseki
from locx.kg.ttl import LOCX, lit

G = CFG["graphs"]
V = G["verdicts"]
VERDICTS = ["Consistent", "Refinement", "Novel", "Conflicting", "Uninformative", "Error"]
RULES = ("verdicts_01_goa_links.ru", "verdicts_02_rules.ru")


def support_by_verdict(stats) -> dict:
    """Per verdict: how many independent author groups (1..5+) and papers back the assertions, and how often
    the claims are findings or hedged everywhere."""
    out = {}
    for v in VERDICTS:
        ss = [s for s in stats if s["verdict"] == v]
        if not ss:
            continue
        n = len(ss)
        papers = sorted(s["n_papers"] for s in ss)
        out[v] = {"assertions": n,
                  "by_n_groups": {str(k) if k < 5 else "5+": c for k, c in
                                  sorted(Counter(min(s["n_groups"], 5) for s in ss).items())},
                  "share_2plus_groups": round(sum(s["n_groups"] >= 2 for s in ss) / n, 3),
                  "mean_groups": round(sum(s["n_groups"] for s in ss) / n, 2),
                  "median_papers": papers[n // 2] if n % 2 else (papers[n // 2 - 1] + papers[n // 2]) / 2,
                  "share_with_finding": round(sum(s["n_papers_finding"] > 0 for s in ss) / n, 3),
                  "share_hedged_in_all_papers": round(sum(s["n_papers_hedged"] == s["n_papers"] for s in ss) / n, 3)}
    return out


def support_only():
    """Recompute support_by_verdict from reports/assertion_stats.tsv and patch it into verdicts.json."""
    csv.field_size_limit(sys.maxsize)
    ints = ("n_groups", "n_papers", "n_papers_finding", "n_papers_hedged")
    with open(REPORTS / "assertion_stats.tsv") as f:
        stats = [{"verdict": r["verdict"], **{k: int(r[k]) for k in ints}} for r in csv.DictReader(f, delimiter="\t")]
    path = REPORTS / "verdicts.json"
    out = json.loads(path.read_text())
    out["support_by_verdict"] = support_by_verdict(stats)
    path.write_text(json.dumps(out, indent=2))
    print("[verdicts] support_by_verdict -> reports/verdicts.json")


def version_of(graph: str) -> str | None:
    rows = fuseki.select(f"""PREFIX owl: <http://www.w3.org/2002/07/owl#>
        SELECT ?v WHERE {{ GRAPH <{graph}> {{ ?o a owl:Ontology ; owl:versionIRI ?v }} }} LIMIT 1""")
    return rows[0]["v"] if rows else None


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--run-id", default=CFG["extract"]["main_run"])
    ap.add_argument("--replace", action="store_true")
    ap.add_argument("--support-only", action="store_true")
    a = ap.parse_args()
    if a.support_only:
        return support_only()
    for t in ("locx:Verdict", "locx:about", "locx:outcome", "locx:strongestEvidence", "locx:curatedFromSamePaper",
              "locx:VerdictComputation"):
        O.term(t)
    run_graph = G["run_prefix"] + a.run_id
    t0 = time.time()
    n = fuseki.count(V)
    if n and not a.replace:
        sys.exit(f"[verdicts] {V} already has {n} triples; rerun with --replace to rebuild it")
    if n:
        fuseki.update(f"DROP SILENT GRAPH <{V}>")
        print(f"[verdicts] dropped {V} ({n} triples) to rebuild")

    # 1. SPARQL rules, under one verdict activity
    started = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S")
    act = f"{LOCX}verdictRun/{started.replace(':', '')}"
    for name in RULES:
        s = fuseki.run_update_file(QUERIES / name, {"%RUN_GRAPH%": run_graph, "%ACTIVITY%": act})
        print(f"[verdicts] {name}: {s:.0f} s ({fuseki.count(V)} triples in {V})", flush=True)
    ended = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S")
    used = [x for x in (version_of(G["go"]), version_of(G["eco"])) if x] + \
           [f"{LOCX}dataset/goa-human", f"{LOCX}ontology", f"{LOCX}run/{a.run_id}"]
    rules = "; ".join(f"queries/{r} (sha256 {hashlib.sha256((QUERIES / r).read_bytes()).hexdigest()[:12]})" for r in RULES)
    act_ttl = (f"@prefix prov: <http://www.w3.org/ns/prov#> .\n@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .\n"
               f"@prefix locx: <http://example.org/locx/> .\n"
               f"@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n"
               f"<{act}> a locx:VerdictComputation ; rdfs:label {lit('verdict computation: assertions compared with GOA')} ;\n"
               f"    rdfs:comment {lit('Rules: ' + rules)} ;\n"
               f"    prov:used " + " , ".join(f"<{u}>" for u in used) + " ;\n"
               f'    prov:startedAtTime "{started}"^^xsd:dateTime ; prov:endedAtTime "{ended}"^^xsd:dateTime .\n')
    path = RDF / "verdict_activity.ttl"
    path.write_text(act_ttl)
    fuseki.append(V, path)

    # 2. read the outcomes back and join them with the support counts
    category = {v: k for k, v in O.values("EvidenceCategory").items()}
    verdict = {}
    for r in fuseki.select(f"""PREFIX locx: <{LOCX}>
        SELECT ?a ?o ?ev ?same WHERE {{ GRAPH <{V}> {{ ?v locx:about ?a ; locx:outcome ?o .
          OPTIONAL {{ ?v locx:strongestEvidence ?ev }} OPTIONAL {{ ?v locx:curatedFromSamePaper ?same }} }} }}"""):
        k = r["a"].rsplit("/", 1)[-1]
        if k in verdict:
            sys.exit(f"[verdicts] assertion {k} got two outcomes")
        ev = category.get(r.get("ev"), "")
        verdict[k] = {"verdict": r["o"].rsplit("/", 1)[-1], "goa_evidence": ev,
                      "goa_experimental": None if not ev else ev in ("experimental", "high_throughput"),
                      "curated_from_same_paper": r.get("same") == "true"}
    stats = {}
    for s in read_jsonl(INTERIM / "support_stats.jsonl"):
        stats[s["assertion"]] = {**s, **verdict.get(s["assertion"], {"verdict": "MISSING"})}
    missing = [k for k in stats if k not in verdict]
    if missing or len(verdict) != len(stats):
        sys.exit(f"[verdicts] {len(stats)} assertions with support, {len(verdict)} verdicts; missing {missing[:5]}")
    nv = fuseki.count(V)
    man = json.loads(fuseki.MANIFEST.read_text()) if fuseki.MANIFEST.exists() else {}
    man[V] = {"file": "(SPARQL UPDATE + verdict_activity.ttl)", "sha256": None, "triples": nv,
              "loaded_at": time.strftime("%Y-%m-%dT%H:%M:%S")}
    fuseki.MANIFEST.write_text(json.dumps(man, indent=1))

    # reports
    groups = [k for k, _, _ in evidence.GROUPS]
    dist = Counter(s["verdict"] for s in stats.values())
    per_tier = {t: Counter(s["verdict"] for s in stats.values() if t in s["tiers"]) for t in ("silver", "discovery")}
    ev = {v: Counter("experimental" if s["goa_experimental"] else "non-experimental only"
                     for s in stats.values() if s["verdict"] == v) for v in ("Consistent", "Refinement", "Conflicting")}
    out = {"run_id": a.run_id, "activity": act, "used": used, "assertions": len(stats),
           "verdicts": {v: dist[v] for v in VERDICTS},
           "verdicts_share": {v: round(dist[v] / len(stats), 3) for v in VERDICTS},
           "per_tier": {t: {v: c[v] for v in VERDICTS} for t, c in per_tier.items()},
           "goa_evidence_behind_verdict": {v: dict(c) for v, c in ev.items()},
           "goa_evidence_group_behind_verdict": {
               v: {g: sum(1 for s in stats.values() if s["verdict"] == v and s["goa_evidence"] == g) for g in groups}
               for v in ("Consistent", "Refinement", "Conflicting")},
           "upgrade_candidates": {v: sum(1 for s in stats.values() if s["verdict"] == v and s["goa_evidence"]
                                         and evidence.RANK[s["goa_evidence"]] > evidence.RANK["high_throughput"])
                                  for v in ("Consistent", "Refinement")},
           "conflicting_with_experimental_goa": sum(1 for s in stats.values() if s["verdict"] == "Conflicting"
                                                    and s["goa_evidence"] == "experimental"),
           "context_dependent": sum(s["context"] for s in stats.values()),
           "curated_from_same_paper": sum(s["curated_from_same_paper"] for s in stats.values()),
           "novel_by_n_groups": dict(sorted(Counter(min(s["n_groups"], 5) for s in stats.values()
                                                    if s["verdict"] == "Novel").items())),
           "support_by_verdict": support_by_verdict(list(stats.values())),
           "triples": nv, "seconds": round(time.time() - t0)}
    (REPORTS / "verdicts.json").write_text(json.dumps(out, indent=2))
    cols = ["symbol", "location", "go_id", "polarity", "verdict", "n_papers", "n_groups", "n_papers_finding",
            "n_papers_background", "n_papers_hedged", "n_claims", "year_first", "year_last", "n_journals",
            "sum_citations", "n_opposing_papers", "curated_from_same_paper", "context", "goa_experimental", "goa_evidence",
            "methods", "organisms", "conditions", "tiers", "uniprot", "pmids", "example_pmid", "example_sentence"]

    def write(path, items):
        with open(path, "w", newline="") as f:
            w = csv.writer(f, delimiter="\t")
            w.writerow(cols)
            for s in items:
                w.writerow([("; ".join(map(str, s[c])) if isinstance(s.get(c), list) else s.get(c)) for c in cols[:-2]]
                           + [s["example"]["pmid"], s["example"]["sentence"]])
    ranked = sorted(stats.values(), key=lambda s: (-s["n_groups"], -s["n_papers_finding"], -s["n_papers"], s["assertion"]))
    write(REPORTS / "assertion_stats.tsv", ranked)
    write(REPORTS / "top_novel.tsv", [s for s in ranked if s["verdict"] == "Novel"][:20])
    write(REPORTS / "top_conflicting.tsv", [s for s in ranked if s["verdict"] == "Conflicting"][:20])
    print(f"[verdicts] {len(stats)} assertions: " + ", ".join(f"{v} {dist[v]} ({dist[v] / len(stats):.0%})" for v in VERDICTS))
    print(f"  strongest GOA evidence: {out['goa_evidence_group_behind_verdict']}")
    print(f"  upgrade candidates {out['upgrade_candidates']}, conflicting with experimental GOA "
          f"{out['conflicting_with_experimental_goa']}, context-dependent {out['context_dependent']}, "
          f"curated from same paper {out['curated_from_same_paper']}")
    print(f"[verdicts] {V}: {nv} triples -> reports/verdicts.json, assertion_stats.tsv ({out['seconds']} s)")


if __name__ == "__main__":
    main()
